    /// True when the same request can be repeated unchanged after a short wait.
    pub const fn retryable(self) -> bool {
        matches!(
            self,
            ErrorCode::OauthProviderError
                | ErrorCode::TooManyAttempts
                | ErrorCode::ConcurrentRunsExceeded
                | ErrorCode::RateLimited
                | ErrorCode::RunTimeout
                | ErrorCode::BillingUnavailable
                | ErrorCode::CheckoutFailed
                | ErrorCode::ServiceUnavailable
                | ErrorCode::HarnessUnavailable
                | ErrorCode::ModelUnavailable
                | ErrorCode::StorageUnavailable
                | ErrorCode::KillSwitchEnabled
                | ErrorCode::Maintenance
        )
    }

